-- Gerado a partir das páginas individuais da TibiaWiki. Revisar antes de executar.
-- Modificadores expressos em percentagem: 100 neutro, >100 fraco, <100 resistente, 0 imune.
-- Não inclui criaturas/elementos sem valor extraído; não inventa 100%.
BEGIN;
ON CONFLICT ("creatureId", "element") DO UPDATE SET "modifier" = EXCLUDED."modifier", "updatedAt" = CURRENT_TIMESTAMP;
COMMIT;
